async function api(path,body,method=body===undefined?'GET':'POST'){const r=await fetch(BASE+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});assert.ok(r.ok,`${method} ${path} HTTP ${r.status}`);return r.json();}
