 await check('部门群聊刷新后恢复运行状态并逐部门显示已提交回复',async()=>{
  const pollGroupId='ui-poll-'+uid;let reads=0;
  const mockGroup={id:pollGroupId,name:'轮询验证-'+uid,createdBy:null,createdAt:Date.now(),updatedAt:Date.now(),running:true,
   activeAgentId:'a1',activeAgentName:'财务部门',members:[{id:'m1',groupId:pollGroupId,agentId:'a1',agentName:'财务部门',position:0,sessionId:null,addedAt:Date.now()},{id:'m2',groupId:pollGroupId,agentId:'a2',agentName:'销售部门',position:1,sessionId:null,addedAt:Date.now()}],
   turns:[{id:'t1',groupId:pollGroupId,sequence:1,userMessage:'轮询状态恢复',status:'running',createdAt:Date.now(),completedAt:null}],
   messages:[{id:'u1',groupId:pollGroupId,turnId:'t1',role:'user',agentId:null,agentName:null,content:'轮询状态恢复',isError:false,createdAt:Date.now()}]};
  await page.route('**/api/agent-groups',route=>route.fulfill({contentType:'application/json',body:JSON.stringify({items:[mockGroup]})}));
  await page.route(`**/api/agent-groups/${pollGroupId}`,route=>{reads++;const state=structuredClone(mockGroup);if(reads>=1)state.messages.push({id:'a1-reply',groupId:pollGroupId,turnId:'t1',role:'agent',agentId:'a1',agentName:'财务部门',content:'预算已核算，等待销售部门确认。',isError:false,createdAt:Date.now()});if(reads>=2){state.running=false;state.turns[0].status='completed';state.turns[0].completedAt=Date.now();}return route.fulfill({contentType:'application/json',body:JSON.stringify(state)});});
  try{await go(`agent-groups/${pollGroupId}/chat`,'轮询验证-'+uid);await expect(page.getByRole('status')).toContainText('财务部门 正在处理本轮消息');await expect(page.locator('.group-members')).toContainText('财务部门 · 正在处理');await expect(page.getByTestId('group-messages')).toContainText('预算已核算，等待销售部门确认。',{timeout:5000});await expect(page.getByRole('status')).toHaveCount(0,{timeout:5000});assert.ok(reads>=2,'页面定期读取服务端群聊状态');}
  finally{await page.unroute(`**/api/agent-groups/${pollGroupId}`);await page.unroute('**/api/agent-groups');}
 });
