 await check('普通对话可通过 /export-html 下载 Pi 原生 HTML',async()=>{
  const previous=await api('/api/sessions',{workflowId:'auto-flow'});
  await go('chat?session='+previous.id,'对话');
  const exportSession=await api('/api/sessions',{workflowId:'auto-flow'});
  await api(`/api/sessions/${exportSession.id}/messages`,{text:'HTML 导出内容校验'});
  await expect.poll(async()=>{const view=await api(`/api/sessions/${exportSession.id}`);return !view.running&&view.transcript.length>0;},{timeout:15000}).toBe(true);
  const delayedTarget=BASE+`/api/sessions/${exportSession.id}`;
  await page.route(delayedTarget,async route=>{await new Promise(resolve=>setTimeout(resolve,600));await route.continue();});
  try{
   await go('chat?session='+exportSession.id,'对话');
   await page.locator('.chat-session.active').evaluate(el=>el.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,clientX:24,clientY:24})));
   await expect(page.locator('.session-context-menu')).toBeVisible();
   const responseWait=page.waitForResponse(response=>/\/api\/sessions\/[^/]+\/export-html$/.test(new URL(response.url()).pathname),{timeout:20000});
   const downloadWait=page.waitForEvent('download',{timeout:20000});
   await page.getByRole('menuitem',{name:'导出 Pi 会话 HTML',exact:true}).click();
   const response=await responseWait;
   assert.equal(new URL(response.url()).pathname,`/api/sessions/${exportSession.id}/export-html`,'HTML 导出必须对应已打开的目标会话');
   assert.equal(response.status(),200);
   const download=await downloadWait;
   assert.equal(download.suggestedFilename(),`pi-session-${exportSession.id}.html`);
   const html=readFileSync(await download.path(),'utf8');
   assert.match(html,/<!doctype html|<html/i);
   const payload=html.match(/<script id="session-data" type="application\/json">([\s\S]*?)<\/script>/)?.[1];
   assert.ok(payload,'Pi HTML 中包含会话数据载荷');
   const sessionData=JSON.parse(Buffer.from(payload,'base64').toString('utf8'));
   assert.ok(sessionData.entries.some(entry=>JSON.stringify(entry).includes('HTML 导出内容校验')));
  }finally{await page.unroute(delayedTarget);}
 });
